package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PatchedConicsTest {
    private final CelestialSystem system=new CelestialSystem(20000,4e9,0);
    @Test void moonEphemerisIsEquatorialPeriodicAndImmutable(){var a=system.moon(0);var b=system.moon(Math.round(system.period()*20));assertEquals(0,a.position().z());assertEquals(0,a.velocity().z());assertTrue(a.position().subtract(b.position()).length()<a.velocity().length()*.06);assertEquals(system.distance(),a.position().length(),1e-8);}
    @Test void entryPreservesGlobalPositionAndVelocity(){long t=500;var moon=system.moon(t);var global=new SpaceState(moon.position().add(new SpaceVector(system.soi()*.9,0,0)),moon.velocity().add(new SpaceVector(-70,20,4)));var path=new SpaceTrajectory(CelestialSystem.EARTH,t,global,system.earthMu());var changed=PatchedConics.trace(path,t,t,system).finalPath();assertEquals(CelestialSystem.MOON,changed.primary());var restored=system.global(changed.primary(),changed.at(t),t);assertTrue(restored.position().subtract(global.position()).length()<1e-8);assertTrue(restored.velocity().subtract(global.velocity()).length()<1e-8);assertEquals(system.moonMu(),changed.mu());}
    @Test void lunarEscapeRestoresEarthChart(){var path=new SpaceTrajectory(CelestialSystem.MOON,0,new SpaceState(new SpaceVector(system.soi()*.9,0,0),new SpaceVector(250,5,0)),system.moonMu());var flight=PatchedConics.trace(path,0,1000,system);assertEquals(CelestialSystem.EARTH,flight.finalPath().primary());var first=flight.legs().getFirst();var a=system.global(path.primary(),path.at(first.until()),first.until());var b=flight.finalPath().at(first.until());assertTrue(a.position().subtract(b.position()).length()<1e-7);assertTrue(a.velocity().subtract(b.velocity()).length()<1e-7);}
    @Test void tightLunarOrbitStaysBoundWithoutEarthForce(){double r=system.moonRadius()*2;var path=new SpaceTrajectory(CelestialSystem.MOON,0,new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(system.moonMu()/r),0)),system.moonMu());var flight=PatchedConics.trace(path,0,100000,system);assertEquals(path,flight.finalPath());assertEquals(1,flight.legs().size());}
    @Test void movingMoonEntryIsDetectedBetweenDistantEndpoints(){long encounter=12000;var moon=system.moon(encounter);var state=new SpaceState(moon.position().add(new SpaceVector(system.soi(),0,0)),moon.velocity().add(new SpaceVector(-250,0,0)));var atEvent=new SpaceTrajectory(CelestialSystem.EARTH,encounter,state,system.earthMu());var path=new SpaceTrajectory(CelestialSystem.EARTH,0,atEvent.at(0),system.earthMu());long hit=PatchedConics.transition(path,0,encounter+12000,system);assertTrue(hit>0&&hit<=encounter+2,"Missed moving SOI: "+hit);}
    @Test void futureManeuverUsesLunarFrameAndProducesAClosedLunarOrbit(){long now=1000;var moon=system.moon(now);double r=system.soi()*.7;var local=new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(system.moonMu()/r),0));var global=system.global(CelestialSystem.MOON,local,now);var path=new SpaceTrajectory(CelestialSystem.EARTH,now,global,system.earthMu());var node=new ManeuverNode(java.util.UUID.randomUUID(),now+1000,-5,0,0,.15);var preview=ManeuverPreview.create(path,now,java.util.List.of(node),system.earthRadius(),2000,system);assertEquals(CelestialSystem.MOON,preview.nodes().getFirst().after().primary());var last=preview.segments().getLast();assertEquals(CelestialSystem.MOON,last.trajectory().primary());assertTrue(last.points().getFirst().position().subtract(last.points().getLast().position()).length()<1e-5);var before=PatchedConics.change(path,now,system).at(node.tick());assertTrue(preview.nodes().getFirst().after().initial().velocity().subtract(before.velocity().add(node.delta(before))).length()<1e-8);}
    @Test void lunarEscapeCrossingDoesNotMissAnExtremelyShallowOutwardArc(){double apo=system.soi()+.001,peri=system.moonRadius()*2,a=(apo+peri)/2;var path=new SpaceTrajectory(CelestialSystem.MOON,0,new SpaceState(new SpaceVector(peri,0,0),new SpaceVector(0,Math.sqrt(system.moonMu()*(2/peri-1/a)),0)),system.moonMu());var ellipse=EllipticArc.of(path.initial(),path.mu());long exit=PatchedConics.transition(path,0,Math.round(ellipse.period()*20),system);assertTrue(exit>0);assertTrue(path.at(exit).position().length()>=system.soi()-.001);}
    @Test void nonIntersectingRadialBandsDoNotScanBillionsOfOrbitalTicks(){for(double r:new double[]{30000,system.distance()*20}){var path=new SpaceTrajectory(CelestialSystem.EARTH,0,new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(system.earthMu()/r),0)),system.earthMu());assertEquals(-1,PatchedConics.transition(path,0,1000000000000L,system));}}
    @Test void exitForecastContinuesUntilRepeatEntryAndRespectsPatchDepth(){var path=new SpaceTrajectory(CelestialSystem.MOON,0,new SpaceState(new SpaceVector(system.soi()*.95,0,0),new SpaceVector(50,40,0)),system.moonMu());var shallow=ManeuverPreview.create(path,0,java.util.List.of(),system.moonRadius(),0,system,1,8);assertEquals(1,shallow.segments().size());assertTrue(shallow.segments().getLast().sphereBoundary(),"Last visible exit must retain its SOI marker");var two=ManeuverPreview.create(path,0,java.util.List.of(),system.moonRadius(),0,system,2,8);assertEquals(2,two.segments().size());var earth=two.segments().getLast();long out=two.segments().getFirst().points().getLast().tick();long next=PatchedConics.transition(earth.trajectory(),out,out+Math.round(system.period()*8*20),system);assertTrue(next-out>system.period()*2*20,"Fixture must reproduce the old horizon gap");assertTrue(earth.sphereBoundary());assertEquals(next,earth.points().getLast().tick(),"Earth patch was extended beyond the next Moon entry");var full=ManeuverPreview.create(path,0,java.util.List.of(),system.moonRadius(),0,system,6,8);assertTrue(full.segments().size()>=3);assertEquals(CelestialSystem.MOON,full.segments().get(2).trajectory().primary());assertEquals(next,full.segments().get(2).points().getFirst().tick());}
    @Test void lunarApproachesUseOneChartAcrossSoiTransitions(){var path=new SpaceTrajectory(CelestialSystem.MOON,0,new SpaceState(new SpaceVector(system.soi()*.95,0,0),new SpaceVector(50,40,0)),system.moonMu());var preview=ManeuverPreview.create(path,0,java.util.List.of(),system.moonRadius(),0,system,3,8);var target=new SpaceTrajectory(CelestialSystem.EARTH,0,system.moon(0),system.earthMu());var result=RendezvousMath.predictPatched(path,preview,target,0,system.earthRadius(),2000,system,CelestialSystem.EARTH,true,3,8);assertFalse(result.approaches().isEmpty());for(var a:result.approaches())assertTrue(a.target().position().subtract(system.moon(a.tick()).position()).length()<1e-4,"Moon ephemeris changed in approach predictor");}
}
